import { readFileSync } from 'node:fs';
const source = readFileSync('client.js', 'utf8');
const { errorText } = await import('data:text/javascript;base64,' + Buffer.from(source).toString('base64'));
for (const [name, body] of [
  ['logged 422 body', {error: {code: 'INVALID_PRICE', message: 'price must be greater than zero'}}],
  ['missing message', {}],
  ['empty nested message', {error: {message: ''}}],
  ['null body', null]
]) {
  try { console.log(name + ': ' + String(errorText(body))); }
  catch (error) { console.log(name + ': ' + error.name + ': ' + error.message); }
}
